import React, { useEffect, useState } from "react";
import { Streamlit, withStreamlitConnection } from "streamlit-component-lib";
import { ReactMic } from "react-mic";

function App() {
  const [record, setRecord] = useState(false);
  const [audioData, setAudioData] = useState(null);

  // Khi component mount, báo cho Streamlit biết là sẵn sàng
  useEffect(() => {
    Streamlit.setComponentReady();
    Streamlit.setFrameHeight();
  }, []);

  // Khi có dữ liệu audio mới, gửi về Streamlit
  useEffect(() => {
    if (audioData) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64Audio = reader.result;
        Streamlit.setComponentValue(base64Audio);
      };
      reader.readAsDataURL(audioData.blob);
    }
  }, [audioData]);

  return (
    <div style={{ textAlign: "center", marginTop: "20px" }}>
      <h2>🎙️ Ghi âm trực tiếp</h2>
      <ReactMic
        record={record}
        className="sound-wave"
        onStop={setAudioData}
        strokeColor="#000000"
        backgroundColor="#FF4081"
        mimeType="audio/wav"
      />
      <div style={{ marginTop: "10px" }}>
        <button onClick={() => setRecord(true)}>Bắt đầu</button>
        <button onClick={() => setRecord(false)}>Dừng</button>
      </div>
    </div>
  );
}

export default withStreamlitConnection(App);
